from torch.utils.cpp_extension import load_inline

min_reduce_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

__global__ void min_reduce_kernel_generic(
    const float* __restrict__ input,
    float* __restrict__ output,
    const long outer_size,
    const long reduce_size,
    const long inner_size,
    const long inner_offset,
    const long inner_count)
{
    long total = outer_size * inner_count;
    long idx = blockIdx.x * blockDim.x + threadIdx.x;
    long stride = gridDim.x * blockDim.x;
    for (; idx < total; idx += stride) {
        long outer_idx = idx / inner_count;
        long local_inner = idx % inner_count;
        long inner_idx = inner_offset + local_inner;
        long base = outer_idx * reduce_size * inner_size + inner_idx;
        float min0 = __ldg(&input[base]);
        float min1 = min0;
        float min2 = min0;
        float min3 = min0;
        float min4 = min0;
        float min5 = min0;
        float min6 = min0;
        float min7 = min0;
        long r = 1;
        for (; r + 7 < reduce_size; r += 8) {
            float v0 = __ldg(&input[base + r * inner_size]);
            float v1 = __ldg(&input[base + (r + 1) * inner_size]);
            float v2 = __ldg(&input[base + (r + 2) * inner_size]);
            float v3 = __ldg(&input[base + (r + 3) * inner_size]);
            float v4 = __ldg(&input[base + (r + 4) * inner_size]);
            float v5 = __ldg(&input[base + (r + 5) * inner_size]);
            float v6 = __ldg(&input[base + (r + 6) * inner_size]);
            float v7 = __ldg(&input[base + (r + 7) * inner_size]);
            min0 = fminf(min0, v0);
            min1 = fminf(min1, v1);
            min2 = fminf(min2, v2);
            min3 = fminf(min3, v3);
            min4 = fminf(min4, v4);
            min5 = fminf(min5, v5);
            min6 = fminf(min6, v6);
            min7 = fminf(min7, v7);
        }
        for (; r < reduce_size; ++r) {
            float v = __ldg(&input[base + r * inner_size]);
            min0 = fminf(min0, v);
        }
        float min_val = fminf(
            fminf(fminf(min0, min1), fminf(min2, min3)),
            fminf(fminf(min4, min5), fminf(min6, min7)));
        output[outer_idx * inner_size + inner_idx] = min_val;
    }
}
__global__ void min_reduce_kernel_vec4(
    const float* __restrict__ input,
    float* __restrict__ output,
    const long outer_size,
    const long reduce_size,
    const long inner_size,
    const long num_vec4)
{
    long total = outer_size * num_vec4;
    long idx = blockIdx.x * blockDim.x + threadIdx.x;
    long stride = gridDim.x * blockDim.x;
    for (; idx < total; idx += stride) {
        long outer_idx = idx / num_vec4;
        long group_idx = idx % num_vec4;
        long inner_start = group_idx * 4;
        long base = outer_idx * reduce_size * inner_size + inner_start;
        float4 minv = __ldg(reinterpret_cast<const float4*>(&input[base]));
        for (long r = 1; r < reduce_size; ++r) {
            float4 v = __ldg(reinterpret_cast<const float4*>(&input[base + r * inner_size]));
            minv.x = fminf(minv.x, v.x);
            minv.y = fminf(minv.y, v.y);
            minv.z = fminf(minv.z, v.z);
            minv.w = fminf(minv.w, v.w);
        }
        long out_base = outer_idx * inner_size + inner_start;
        output[out_base + 0] = minv.x;
        output[out_base + 1] = minv.y;
        output[out_base + 2] = minv.z;
        output[out_base + 3] = minv.w;
    }
}
torch::Tensor min_reduce_cuda(torch::Tensor input, int64_t dim) {
    input = input.contiguous();
    auto sizes = input.sizes();
    int ndim = sizes.size();
    long outer_size = 1;
    for (int i = 0; i < dim; ++i) {
        outer_size *= sizes[i];
    }
    long reduce_size = sizes[dim];
    long inner_size = 1;
    for (int i = dim + 1; i < ndim; ++i) {
        inner_size *= sizes[i];
    }
    std::vector<int64_t> out_sizes;
    for (int i = 0; i < ndim; ++i) {
        if (i != dim) {
            out_sizes.push_back(sizes[i]);
        }
    }
    auto output = torch::empty(out_sizes, input.options());
    int threads = 256;
    long vec4_inner = (inner_size % 4 == 0) ? inner_size : 0;
    long remainder = inner_size - vec4_inner;
    if (vec4_inner > 0) {
        long num_vec4 = vec4_inner / 4;
        long total_vec = outer_size * num_vec4;
        int blocks_vec = (int)((total_vec + threads - 1) / threads);
        if (blocks_vec > 65535) blocks_vec = 65535;
        if (blocks_vec < 1) blocks_vec = 1;
        min_reduce_kernel_vec4<<<blocks_vec, threads>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            outer_size,
            reduce_size,
            inner_size,
            num_vec4
        );
    }
    if (remainder > 0) {
        long total = outer_size * remainder;
        int blocks = (int)((total + threads - 1) / threads);
        if (blocks > 65535) blocks = 65535;
        if (blocks < 1) blocks = 1;
        min_reduce_kernel_generic<<<blocks, threads>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            outer_size,
            reduce_size,
            inner_size,
            vec4_inner,
            remainder
        );
    }
    return output;
}
